let lessonWorker=null;
const lessonReviewIntervals=[2,4,7,14,30],lessonDayMs=86400000;
function lessonReviewFor(id){return state.skillLessonReviews?.[id]||null}
function dueLessonIndex(){const now=Date.now(),ready=GUIDED_LESSONS.map((lesson,index)=>({index,review:lessonReviewFor(lesson.id)})).filter(item=>!item.review||Number(item.review.dueAt)<=now);ready.sort((a,b)=>{if(!a.review&&!b.review)return a.index-b.index;if(!a.review)return -1;if(!b.review)return 1;return Number(a.review.dueAt)-Number(b.review.dueAt)});return ready[0]?.index??null}
