function lessonFinish(c){const d=lessonState;if(!c.isGameOver())return false;d.waiting=false;if(c.isCheckmate()&&c.turn()==='b'){d.phase='complete';d.message='Checkmate! You solved it your own way.';recordLessonReview(lessonCurrent().lesson.id,true);state.checks[dailyChecklistKey()]||={};state.checks[dailyChecklistKey()].lesson=true;save()}else d.message=c.isStalemate()?'Stalemate: the king has no legal move but is not in check. Watch again or restart to try a different finish.':'This attempt ended in a draw. Restart and try a different approach.';return true}
