function lessonTryMove(c,move,d){const {lesson,moves}=lessonCurrent();if(lesson.moves){const expected=moves[d.attempt.length],code=move.from+move.to+(move.promotion&&c.get(move.from)?.type==='p'&&['1','8'].includes(move.to[1])?move.promotion:'');if(code!==expected){d.message='Try another move. '+lesson.tip;render();return}const played=c.move(move);d.attempt.push(expected);if(d.attempt.length<moves.length){const reply=moves[d.attempt.length];c.move(uci(reply));d.attempt.push(reply)}if(d.attempt.length>=moves.length){d.phase='complete';d.message='You found the whole idea!';recordLessonReview(lesson.id,true);state.checks[dailyChecklistKey()]||={};state.checks[dailyChecklistKey()].lesson=true;save()}else d.message='Correct. Find the next move.';selectedSquare=null;render();return}let played;try{played=c.move(move)}catch{}if(!played){d.message='That move is not legal. Keep your king safe and choose a highlighted square.';render();return}selectedSquare=null;d.attempt.push(played.from+played.to+(played.promotion||''));if(lessonFinish(c)){render();return}lessonRequestReply(c,d)}
