document.addEventListener('keydown',event=>{if(event.key==='Escape'&&dragGesture){event.preventDefault();cancelPieceDrag()}});
function hideDragSource(d){
 if(!d.ghost||!d.previewReady)return;
 const origin=d.board.querySelector(`[data-square="${d.from}"]`);
 if(!origin)return;
 d.hiddenSquare?.classList.remove('drag-origin');
 d.hiddenSquare=origin;
 origin.classList.add('drag-origin');
 for(const animation of origin.querySelector('img')?.getAnimations?.()||[])animation.cancel();
}
function clearDrag(){
 const d=dragGesture;
 dragGesture=null;
 if(d){
  d.ghost?.remove();
  d.hiddenSquare?.classList.remove('drag-origin');
  if(d.square.hasPointerCapture(d.pointer))d.square.releasePointerCapture(d.pointer);
 }
 return d;
}
function handleBoardSquare(square){
 if(view==='game')handleGameSquare(square);
 else if(view==='training')trySquare(square);
 else if(view==='learn')lessonSquare(square);
 else if(view==='endgame-demo')endgameTrySquare(square);
}
function dragDestination(d,event){
 const squareAt=(x,y)=>{
  const square=document.elementFromPoint(x,y)?.closest('.square[data-square]');
  return square?.closest('.board')===d.board?square:null;
 };
 // Use the dragged piece's position at release, even without a final pointermove.
 const x=event.clientX+d.centerX-d.x;
 const y=event.clientY+d.centerY-d.y;
 return squareAt(x,y)||squareAt(event.clientX,event.clientY);
}
document.addEventListener('pointerup',e=>{
 const press=e.pointerType==='touch'&&touchPress?.pointer===e.pointerId?touchPress:null;
 if(press)touchPress=null;
 const d=dragGesture?.pointer===e.pointerId?clearDrag():null;
 if(press){
  // A touch is complete at release, even when the browser omits its click.
  handledTouchBoard=press.square.closest('.board');
  const distance=Math.hypot(e.clientX-press.x,e.clientY-press.y);
  const released=document.elementFromPoint(e.clientX,e.clientY);
  if(distance<=6&&released?.closest('.square[data-square]')===press.square){
   handleBoardSquare(press.square.dataset.square);
   return;
  }
 }
 if(!d)return;
 const destination=dragDestination(d,e);
 // A quick release can reach another square before any pointermove is delivered.
 const moved=Math.hypot(e.clientX-d.x,e.clientY-d.y)>6;
 if(!moved&&(!destination||destination===d.square))return;
 suppressBoardClick=true;
 setTimeout(()=>suppressBoardClick=false,0);
 if(!destination||destination.dataset.square===d.from)return;
 dragDropInProgress=true;
 try{
  if(view==='game')gameSelection=d.from;
  else selectedSquare=d.from;
  handleBoardSquare(destination.dataset.square);
 }finally{dragDropInProgress=false}
});
document.addEventListener('pointercancel',e=>{
 if(touchPress?.pointer===e.pointerId)touchPress=null;
 if(dragGesture?.pointer===e.pointerId)clearDrag();
});
window.addEventListener('blur',()=>{
 touchPress=null;
 clearDrag();
});
document.addEventListener('click',e=>{
 const square=e.target.closest('.board .square[data-square]');
 if(!square)return;
 const followsTouch=handledTouchBoard===square.closest('.board')&&(e.detail>0||e.pointerType==='touch');
 if(followsTouch||suppressBoardClick){e.preventDefault();e.stopImmediatePropagation();return}
 handleBoardSquare(square.dataset.square);
},true);
document.addEventListener('keydown',event=>{if(!['ArrowLeft','ArrowRight'].includes(event.key)||event.altKey||event.ctrlKey||event.metaKey||event.shiftKey)return;const target=event.target;if(document.querySelector('dialog[open]')||target?.closest?.('input,textarea,select,summary,[contenteditable]')||target?.isContentEditable)return;const delta=event.key==='ArrowRight'?1:-1;if(view==='game'&&state.match){event.preventDefault();browseLiveHistory(delta)}else if(view==='games'&&reviewGameIndex!=null){event.preventDefault();const total=state.games?.[reviewGameIndex]?.moves?.length||0;gameStep=clamp(gameStep+delta,0,total);render()}});

// Animate only a single forward move on the same board position.
function boardSlide(oldBoard,newBoard){
 if (dragDropInProgress || !['game','arena-live','games'].includes(view) || !oldBoard.dataset.fen || oldBoard.dataset.fen!==newBoard.dataset.before || !newBoard.dataset.from || !newBoard.dataset.to) return null;
 return {from:newBoard.dataset.from,to:newBoard.dataset.to,flags:newBoard.dataset.flags};
}
function animateBoardSlide(board,move){
 if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;
 const squares=[...board.children];
 const square=name=>squares.find(el=>el.getAttribute('aria-label')?.startsWith(name+','));
 const slide=(from,to)=>{const source=square(from),target=square(to),piece=target?.querySelector('.piece-img');if(!source||!target||!piece)return;const a=source.getBoundingClientRect(),b=target.getBoundingClientRect();target.style.zIndex='10';const animation=piece.animate([{transform:`translate(${a.left-b.left}px,${a.top-b.top}px)`},{transform:'translate(0,0)'}],{duration:120,easing:'ease-out'});animation.finished.then(()=>{target.style.zIndex=''},()=>{target.style.zIndex=''})};
 slide(move.from,move.to);
 if(move.flags?.includes('k'))slide('h'+move.from[1],'f'+move.from[1]);
 if(move.flags?.includes('q'))slide('a'+move.from[1],'d'+move.from[1]);
}

function settingsPicker(id,label,choices,current){return `<div class="settings-field"><span>${label}</span><div class="bot-picker"><select id="${id}" class="bot-picker-value" tabindex="-1" aria-hidden="true">${Object.entries(choices).map(([k,v])=>`<option value="${k}" ${k===current?'selected':''}>${v}</option>`).join('')}</select><details class="bot-picker-details"><summary aria-label="${label}"><span class="bot-picker-current"></span><span aria-hidden="true">⌄</span></summary><div class="bot-picker-list" aria-label="${label} options"></div></details></div></div>`}
function updateSettingsPreview(){const preview=$('#settings-preview');if(!preview)return;const chess=new Chess();preview.innerHTML=[...'87654321'].flatMap((r,ri)=>[...'abcdefgh'].map((f,fi)=>{const p=chess.get(f+r);const image=p?`<img src="${pieceURL(pieceTheme,p.color,p.type)}" alt="">`:'';return `<span class="square ${(ri+fi)%2?'dark':''}">${image}</span>`})).join('')}
