 $('#settings-premoves').onchange=e=>{premovesEnabled=e.target.checked;try{localStorage.setItem('chess-premoves',premovesEnabled?'on':'off')}catch{};if(!premovesEnabled&&state.match){clearPremoves(state.match);gameSelection=null;save();render()}};
